import { describe, expect, it } from "vitest";

import {
  encodeSecret,
  normalizeIptablesSave,
  parseProbeOutput,
  probeArgv,
} from "./harness";

describe("normalizeIptablesSave", () => {
  it("keeps rules and user chains, drops headers, policies and counters", () => {
    expect(
      normalizeIptablesSave([
        "# Generated by iptables-save",
        "*filter",
        ":INPUT ACCEPT [0:0]",
        ":DOCKER - [0:0]",
        "-A FORWARD -j DOCKER",
        "COMMIT",
      ]),
    ).toEqual(["-A FORWARD -j DOCKER", ":DOCKER -"]);
  });

  it("ignores an empty table the kernel loaded on first use", () => {
    const before = ["*filter", "-A FORWARD -j DOCKER", "COMMIT"];
    const after = [
      ...before,
      "*raw",
      ":PREROUTING ACCEPT [12:840]",
      ":OUTPUT ACCEPT [3:180]",
      "COMMIT",
    ];
    expect(normalizeIptablesSave(after)).toEqual(normalizeIptablesSave(before));
  });

  it("still sees a rule a cell left behind", () => {
    const before = ["*filter", "-A FORWARD -j DOCKER", "COMMIT"];
    const after = [
      "*filter",
      "-A FORWARD -j DOCKER",
      "-A FORWARD -d 10.0.0.2 -j ACCEPT",
      "COMMIT",
    ];
    expect(normalizeIptablesSave(after)).not.toEqual(
      normalizeIptablesSave(before),
    );
  });
});

describe("probeArgv", () => {
  it("refuses TCP on :80 and :443 under the proxy", () => {
    expect(() => probeArgv([{ kind: "tcp", host: "h", port: 80 }])).toThrow();
    expect(() => probeArgv([{ kind: "tcp", host: "h", port: 443 }])).toThrow();
  });

  it("allows them for the no-policy control and keeps the flag off the wire", () => {
    const argv = probeArgv([
      { kind: "tcp", host: "h", port: 80, unproxied: true },
    ]);
    expect(argv[3]).toBe(
      JSON.stringify([{ kind: "tcp", host: "h", port: 80 }]),
    );
  });

  it("never puts a canary or marker in the argv in clear", () => {
    const argv = probeArgv([
      { kind: "canary_scan", canaries: ["osbit-canary-x"], namePattern: "X" },
      { kind: "https", url: "https://h/", marker: "osbit-canary-y" },
    ]);
    expect(argv.join(" ")).not.toContain("osbit-canary-");
  });
});

describe("https_headers probe", () => {
  const spec = {
    kind: "https_headers" as const,
    url: "https://h/anything/daemon-event",
    headers: { "X-Daemon-Token": "PLACEHOLDER-P" },
    markers: ["osbit-canary-c", "PLACEHOLDER-P"],
  };

  it("builds a wire spec with base64 markers and the headers as given", () => {
    const argv = probeArgv([spec]);
    expect(JSON.parse(argv[3] ?? "")).toEqual([
      {
        kind: "https_headers",
        url: spec.url,
        headers: spec.headers,
        markers_b64: [
          encodeSecret("osbit-canary-c"),
          encodeSecret("PLACEHOLDER-P"),
        ],
      },
    ]);
  });

  it("never puts a marker in the argv in clear and sends a POST", () => {
    const joined = probeArgv([spec]).join(" ");
    expect(joined).not.toContain("osbit-canary-c");
    expect(joined).toContain('method="POST"');
  });

  it("parses one boolean per marker and nothing else from the body", () => {
    const out = parseProbeOutput(
      JSON.stringify([
        {
          kind: "https_headers",
          ok: true,
          status: 200,
          markersFound: [true, false],
          body: "SHOULD-NOT-SURFACE",
        },
      ]),
    );
    expect(out).toHaveLength(1);
    expect(out[0]).toMatchObject({ status: 200, markersFound: [true, false] });
    expect(JSON.stringify(out)).not.toContain("SHOULD-NOT-SURFACE");
  });

  it("drops a markersFound that is not all booleans", () => {
    const [r] = parseProbeOutput(
      JSON.stringify([
        { kind: "https_headers", ok: true, markersFound: [true, "x"] },
      ]),
    );
    expect(r?.markersFound).toBeUndefined();
  });
});
